import type { ThreadId } from "./selection.ts";
import { type Message, type MessageIdx, messageText } from "./thread.ts";
import type { ThreadTree } from "./threads.ts";

/** One user interaction, captured as it happens. The unit of evidence about
 * what this user understands. */
export type Interaction = {
  thread: ThreadId;
  /** Index into that thread's `messages`. With `thread`, this is the citable
   * address. A learning thread's ask is its own message 0, so there is no
   * special case. */
  index: MessageIdx;
  /** The thread's seed, then its blocks before the turn - which are messages
   * 0 to index-1, so their addresses are their positions. Identical across
   * interactions in the same thread up to their split point; the prompt cache
   * depends on that. */
  prefix: {
    seed: string | undefined;
    messages: ReadonlyArray<Message>;
  };
  /** The user's turn. */
  text: string;
};

/** The interaction the user just made: the turn at `index` in `thread`. */
export function interactionAt(
  tree: ThreadTree,
  thread: ThreadId,
  index: MessageIdx,
): Interaction {
  const node = tree.get(thread);
  const messages = node.thread.messages;
  const message = messages[index];
  if (!message) {
    throw new Error(`no message ${index} in thread ${thread}`);
  }
  if (message.role !== "user") {
    throw new Error(`message ${index} in thread ${thread} is not a user turn`);
  }
  return {
    thread,
    index,
    prefix: {
      // Only a learning thread's seed is prose; a graph update's seed is
      // content blocks, and those threads have no interactions in them.
      seed: typeof node.thread.seed === "string" ? node.thread.seed : undefined,
      messages: messages.slice(0, index),
    },
    text: messageText(message),
  };
}

import { type Message, messageText } from "./thread.ts";

/** Declared here rather than in threads.ts because an anchor is meaningless
 * without one, and threads.ts will import this module. */
export type ThreadId = string & { readonly __brand: "ThreadId" };

/** A selection over the transcript, stored as character offsets into message
 * text rather than as a live DOM Range: the browser's Range dies the moment the
 * user clicks the learning pane, and the transcript is append-only, so offsets
 * stay valid while a message is still streaming.
 *
 * `msg` is an absolute index into the owning thread's turns, `offset` a
 * character offset into that turn's text. */
export type Point = { msg: number; offset: number };
/** `start` precedes `end` in document order; `thread` is the thread whose
 * transcript the range indexes, i.e. the parent of whatever it opens. */
export type Anchor = { thread: ThreadId; start: Point; end: Point };

/** A committed highlight: the passage, plus the thread it opens. The opened
 * thread's id cannot live on the anchor, because `anchor.thread` already names
 * the other end of the edge - the parent. */
export type Mark = { thread: ThreadId; anchor: Anchor };

/** A run of one message's text: plain, a committed mark, or the live selection
 * the user has just dragged and not yet acted on. */
export type Segment = {
  start: number;
  end: number;
  /** The thread this run opens, or null for plain text and the live range. */
  thread: ThreadId | null;
  live: boolean;
};

/** True when `live` intersects any committed mark, which makes it unusable:
 * a passage owned by two threads has no honest meaning as an edge in the tree. */
export function overlaps(marks: ReadonlyArray<Mark>, live: Anchor): boolean {
  return marks.some(
    (m) => before(m.anchor.start, live.end) && before(live.start, m.anchor.end),
  );
}

function before(a: Point, b: Point): boolean {
  return a.msg !== b.msg ? a.msg < b.msg : a.offset < b.offset;
}

/** Splits message `i` into plain, marked and live runs, left to right.
 * `marks` are pairwise disjoint; `live` may overlap them, and wins where it
 * does, so the user still sees what they dragged. */
export function segments(
  marks: ReadonlyArray<Mark>,
  live: Anchor | null,
  i: number,
  length: number,
): Segment[] {
  const liveClip = clipToMessage(live, i, length);
  const runs: Segment[] = [];
  for (const mark of marks) {
    const clip = clipToMessage(mark.anchor, i, length);
    if (!clip) continue;
    for (const part of subtract(clip, liveClip)) {
      runs.push({ ...part, thread: mark.thread, live: false });
    }
  }
  if (liveClip) runs.push({ ...liveClip, thread: null, live: true });
  runs.sort((a, b) => a.start - b.start);

  const out: Segment[] = [];
  let at = 0;
  for (const run of runs) {
    if (run.start > at) {
      out.push({ start: at, end: run.start, thread: null, live: false });
    }
    out.push(run);
    at = run.end;
  }
  if (at < length) {
    out.push({ start: at, end: length, thread: null, live: false });
  }
  return out;
}

type Run = { start: number; end: number };

function subtract(run: Run, hole: Run | null): Run[] {
  if (!hole || hole.end <= run.start || hole.start >= run.end) return [run];
  const out: Run[] = [];
  if (run.start < hole.start) out.push({ start: run.start, end: hole.start });
  if (run.end > hole.end) out.push({ start: hole.end, end: run.end });
  return out;
}

/** The portion of `anchor` falling inside message `i`, or null. */
function clipToMessage(
  anchor: Anchor | null,
  i: number,
  length: number,
): { start: number; end: number } | null {
  if (!anchor) return null;
  if (i < anchor.start.msg || i > anchor.end.msg) return null;
  const start = i === anchor.start.msg ? anchor.start.offset : 0;
  const end = i === anchor.end.msg ? anchor.end.offset : length;
  return end > start ? { start, end } : null;
}

export function anchorText(
  anchor: Anchor,
  messages: ReadonlyArray<Message>,
): string {
  const parts: string[] = [];
  for (let i = anchor.start.msg; i <= anchor.end.msg; i++) {
    const text = messages[i] ? messageText(messages[i]) : "";
    const clip = clipToMessage(anchor, i, text.length);
    if (clip) parts.push(text.slice(clip.start, clip.end));
  }
  return parts.join("\n\n");
}

import type Anthropic from "@anthropic-ai/sdk";
import { citationText } from "./citation.ts";
import type { Interaction } from "./interactions.ts";
import { type Anchor, anchorText, type ThreadId } from "./selection.ts";
import type { Message, MessageIdx } from "./thread.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

/** Learning mode: the agent is explaining work that already happened, to a
 * user who chose the passage they are stuck on. */
export const LEARNING_SYSTEM = [
  "You are helping a user understand engineering work that was done for them.",
  "They will show you a transcript and point at a passage they picked out.",
  "Answer about that passage specifically, in plain language, and assume the",
  "user has not followed the reasoning that produced it. Be concise, and do",
  "not restate the whole transcript back to them.",
  "",
  "You may be shown a knowledge graph: what we believe this user already",
  "understands, one line per node and edge, each with an id and a level on the",
  "scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent. Pitch your answer to",
  "it: build on what they are fluent in and slow down on what they are not.",
  "The overview is titles only, so call the `get` tool with the ids of",
  "anything you are about to lean on to read its full description and the",
  "notes on this user. You cannot change the graph; do not offer to.",
].join(" ");

/** The context a learning thread is seeded with: its parent's own seed plus
 * the parent's transcript up to the anchor. `seed` is emitted verbatim -
 * wrapping or re-labelling it would nest the framing one layer deeper at
 * every level. The passage and the ask are not here: they are the thread's
 * first visible turn. */
export function contextSeed(
  seed: string | undefined,
  messages: ReadonlyArray<Message>,
  anchor: Anchor,
  graph?: string,
): string {
  const sections = [];
  // Only the topmost learning thread renders the graph: a deeper thread's
  // `seed` is its parent's, which already carries it, and repeating it would
  // show the model the same overview once per level.
  if (seed) sections.push(seed);
  else if (graph)
    sections.push(`What this user already understands:\n${graph}`);
  sections.push(transcript(visibleTo(messages, anchor)));
  return sections.join("\n\n");
}

/** The user's opening turn: the passage they highlighted and what they asked
 * of it. Visible, because it is an interaction like any other. */
export function askTurn(
  anchor: Anchor,
  messages: ReadonlyArray<Message>,
  action: Action,
): string {
  const quote = anchorText(anchor, visibleTo(messages, anchor));
  return `Selected: "${quote}"\n\n${ask(action)}`;
}

/** The parent's transcript truncated after the message the selection ends in:
 * nothing later than the passage is context for asking about it. */
function visibleTo(
  messages: ReadonlyArray<Message>,
  anchor: Anchor,
): ReadonlyArray<Message> {
  return messages.slice(0, anchor.end.msg + 1);
}

/** Graph update mode: one detached pass over a single user interaction, whose
 * only output is whatever it writes to the graph through its tools. */
export const GRAPH_UPDATE_SYSTEM = [
  "You maintain a knowledge graph of what one user understands. You are shown",
  "a single interaction that user just made, in the context of the thread it",
  "happened in and the graph as it stands.",
  "",
  "Ask: what domain concepts is this interaction about, are they in the graph",
  "already, what understanding does the user demonstrate here, and does",
  "anything here read as a gap or a misconception. A node is a concept - an",
  "idea a person can understand or fail to understand - never a file, a",
  "message or a line of code. Set `level` from what the interaction reveals,",
  "on the scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent. The scale",
  "cannot express a misconception - a confidently held wrong belief reads as",
  "fluent - so put misconceptions, and anything else about how this user holds",
  "the idea, in `notes`.",
  "",
  "Touch only what this interaction is about; leave the rest of the graph",
  "alone. Keep the graph small and coarse: update the node that already covers",
  "a concept rather than minting a second one for it, and split a concept only",
  "when the split expresses something real about this user's understanding. A",
  "concept the user merely brushed past does not need a node.",
  "",
  "Ground every note about this user in what they actually did. Each block of",
  "the transcript is labelled with its address, `@message:<thread>:<index>`,",
  "including the interaction itself. A claim about what this user understands",
  "or misunderstands must cite the addresses it rests on, written verbatim in",
  "the note; do not assert anything you cannot point at.",
  "",
  "Most interactions reveal nothing. If this one does not, change nothing and",
  "yield: doing nothing is the expected outcome, not a failure. The yield tool",
  "takes no input, and nothing you say outside the tools is read: the graph",
  "writes are the whole output of this thread, so do not narrate or summarize",
  "them.",
].join(" ");

/** Two blocks: the cacheable prefix - the base prompt, the thread's seed and
 * the transcript before the turn, all of which every earlier interaction in
 * this thread shares - then the volatile tail, which starts with the graph
 * because the previous update just rewrote it. */
export function graphUpdatePrompt(
  interaction: Interaction,
  graph: string,
): Anthropic.ContentBlockParam[] {
  const prefix = [GRAPH_UPDATE_PREAMBLE];
  if (interaction.prefix.seed)
    prefix.push(`How this thread was framed:\n${interaction.prefix.seed}`);
  if (interaction.prefix.messages.length > 0)
    prefix.push(
      `The thread up to this interaction:\n${transcript(interaction.prefix.messages, interaction.thread)}`,
    );
  return [
    {
      type: "text",
      text: prefix.join("\n\n"),
      cache_control: { type: "ephemeral" },
    },
    {
      type: "text",
      text: [
        `The knowledge graph as it stands:\n${graph}`,
        `The interaction, at ${citationText({ thread: interaction.thread, index: interaction.index })}:\nUser: ${interaction.text}`,
        GRAPH_UPDATE_QUESTIONS,
      ].join("\n\n"),
    },
  ];
}

const GRAPH_UPDATE_PREAMBLE =
  "Below is one interaction a user made while an engineering agent worked on a task for them, and the context it happened in.";

const GRAPH_UPDATE_QUESTIONS = [
  "What domain concepts does this interaction touch, and are they in the",
  "graph? What understanding does it demonstrate, and what does it suggest",
  "the user is missing? Update the graph so it reflects that, and nothing",
  "else - then yield.",
].join(" ");

/** With `thread`, every block is labelled with its address, so the model can
 * cite it back. Indices are positions in that thread's `messages`, which is
 * append-only, so an address stays valid for the life of the page. */
function transcript(
  messages: ReadonlyArray<Message>,
  thread?: ThreadId,
): string {
  return messages
    .map((m, i) => {
      const who = m.role === "user" ? "User" : "Assistant";
      const at = thread
        ? ` (${citationText({ thread, index: i as MessageIdx })})`
        : "";
      return `${who}${at}: ${line(m)}`;
    })
    .join("\n\n");
}

function line(message: Message): string {
  return message.type === "text"
    ? message.text
    : `[called tool ${message.call.name} with ${message.call.inputJson}]`;
}

/** How the thread was opened, shown at the top of its pane so the user can see
 * what they asked for. */
export function actionLabel(action: Action): string {
  switch (action.type) {
    case "explain":
      return "I don't understand this.";
    case "quiz":
      return "Quiz me on this.";
    case "query":
      return action.text;
  }
}

/** What the user is asking for, in their own voice: this is a user turn now,
 * not a briefing written about them. */
function ask(action: Action): string {
  switch (action.type) {
    case "explain":
      return "I don't understand this. Explain what it means and why it is there.";
    case "quiz":
      return "Quiz me on this. Ask one question that checks whether I understand it, and wait for my answer.";
    case "query":
      return action.text;
  }
}

import { type Action, actionLabel } from "./prompt.ts";
import type { ThreadId } from "./selection.ts";
import {
  Binder,
  cls,
  mountStyle,
  type PostRenderEventBus,
  ref,
  sanitize,
  showKeyed,
  type View,
} from "./vamp.ts";
import type { AppEvent } from "./view.ts";

export type { Action };

export type State = {
  /** The text the user highlighted, or null when nothing is selected. */
  selection: string | null;
  /** The live selection intersects a committed mark, so no action is offered. */
  overlapping: boolean;
  query: string;
  /** The passages in this thread that already own a thread, offered as a way
   * back into them when nothing is selected. */
  marks: ReadonlyArray<{ thread: ThreadId; text: string }>;
};

/** Where the live selection ended, in viewport coordinates: the popup is
 * fixed-position, so it needs no knowledge of which pane scrolled. */
export type PopupState = { at: { x: number; y: number } };

export type Msg =
  | { type: "ACTION"; action: Action }
  /** Open the reflect layer on this passage without an action, so the user can
   * type their own question into the pane's composer. */
  | { type: "ASK" }
  | { type: "QUERY_CHANGED"; query: string }
  /** One of the existing passages was picked out of the list. */
  | { type: "MARK_CLICKED"; thread: ThreadId };

const paneClass = cls("learning-pane");
const popupClass = cls("selection-popup");
const emptyClass = cls("learning-empty");
const quoteClass = cls("learning-quote");
const actionsClass = cls("learning-actions");
const warnClass = cls("learning-warn");
const markListClass = cls("learning-mark-list");

mountStyle(`
.${paneClass} {
  position: sticky;
  top: 4rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${emptyClass} {
  opacity: 0.5;
  font-style: italic;
}
.${markListClass} {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.${markListClass} button {
  font: inherit;
  font-size: 0.85rem;
  text-align: left;
  width: 100%;
  padding: 0.35rem 0.5rem;
  border: none;
  border-left: 3px solid #f0b429;
  background: rgba(0, 0, 0, 0.03);
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.${markListClass} button:hover {
  background: rgba(0, 0, 0, 0.08);
}
.${warnClass} {
  font-style: italic;
  color: #a35200;
}
.${quoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  padding-left: 0.75rem;
  max-height: 12rem;
  overflow-y: auto;
  font-size: 0.9rem;
}
.${actionsClass} {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
}
.${actionsClass} button {
  font: inherit;
  text-align: left;
  padding: 0.5rem 0.75rem;
}
.${actionsClass} textarea {
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
.${popupClass} {
  position: fixed;
  z-index: 10;
  transform: translate(-50%, 0.5rem);
  width: 16rem;
  padding: 0.5rem;
  border-radius: 0.5rem;
  border: 1px solid rgba(0, 0, 0, 0.15);
  background: #fff;
  box-shadow: 0 0.5rem 1.5rem rgba(0, 0, 0, 0.18);
}
`);

/** The same three affordances as the pane, floated next to the passage the
 * user just dragged. This is the only way into a reflection thread when the
 * pane is not on screen: at layer 0, and out of the reflect thread itself. */
export class SelectionPopup implements View<PopupState, Msg> {
  container: HTMLElement;
  /** The popup is portalled to the body rather than rendered where it is
   * mounted: it floats over a pane, and the panes are scrolling grid columns
   * that would clip it and reserve layout for it. */
  private readonly portal: HTMLElement;
  private b: Binder<PopupState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: PopupState,
  ) {
    const explainRef = ref("popup-explain");
    const quizRef = ref("popup-quiz");
    const askRef = ref("popup-ask");

    this.container = container;
    this.portal = document.createElement("div");
    this.portal.className = `${popupClass} ${actionsClass}`;
    this.portal.innerHTML = sanitize`
      <button type="button" data-ref="${explainRef}">${actionLabel({ type: "explain" })}</button>
      <button type="button" data-ref="${quizRef}">${actionLabel({ type: "quiz" })}</button>
      <button type="button" data-ref="${askRef}">Ask your own question…</button>
    `;
    document.body.append(this.portal);
    this.b = new Binder(this.portal, initialState);

    // Selecting text and then reaching for the popup collapses the browser
    // selection on mousedown, which would dismiss the popup before the click
    // lands; the anchor is already captured, so the default is not wanted.
    this.portal.addEventListener("mousedown", (e: MouseEvent) => {
      e.preventDefault();
    });
    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );
    // A textarea here cannot be typed into: the popup suppresses mousedown to
    // keep the selection alive, so it can never take focus. The composer in the
    // pane can, so this hands off to it.
    this.b
      .ref(askRef)
      .addEventListener("click", () => dispatch({ type: "ASK" }));

    this.b.bindContainerStyle((s) => ({
      left: `${s.at.x}px`,
      top: `${s.at.y}px`,
    }));
  }

  sync(state: PopupState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.portal.remove();
  }
}

export type PaneCtx = { bus: PostRenderEventBus<AppEvent> };

/** One already-opened passage in the list. Its own view so the list can be
 * keyed by thread rather than rebuilt on every sync. */
class MarkItem implements View<{ text: string }, { type: "CLICK" }> {
  container: HTMLElement;
  private b: Binder<{ text: string }>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: { type: "CLICK" }) => void,
    initialState: { text: string },
  ) {
    const buttonRef = ref("mark-item");
    container.innerHTML = sanitize`<button type="button" data-ref="${buttonRef}"></button>`;
    this.container = container;
    this.b = new Binder(container, initialState);
    this.b
      .ref(buttonRef)
      .addEventListener("click", () => dispatch({ type: "CLICK" }));
    this.b.bindText(buttonRef, (s) => s.text);
  }

  sync(state: { text: string }): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

export class LearningPane implements View<State, Msg, PaneCtx> {
  container: HTMLElement;
  private b: Binder<State>;
  private readonly unsubscribe: () => void;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
    ctx: PaneCtx,
  ) {
    const emptyRef = ref("empty");
    const bodyRef = ref("body");
    const quoteRef = ref("quote");
    const explainRef = ref("explain");
    const quizRef = ref("quiz");
    const queryRef = ref("query");
    const warnRef = ref("warn");
    const markListRef = ref("mark-list");

    container.className = paneClass;
    container.innerHTML = sanitize`
      <p class="${emptyClass}" data-ref="${emptyRef}">Select some text to get started.</p>
      <ul class="${markListClass}" data-ref="${markListRef}"></ul>
      <p class="${warnClass}" data-ref="${warnRef}">Select a non-overlapping section.</p>
      <div class="${actionsClass}" data-ref="${bodyRef}">
        <blockquote class="${quoteClass}" data-ref="${quoteRef}"></blockquote>
        <button type="button" data-ref="${explainRef}">I don't understand this.</button>
        <button type="button" data-ref="${quizRef}">Quiz me on this.</button>
        <textarea data-ref="${queryRef}" rows="2" placeholder="Ask your own question…"></textarea>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initialState);

    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );

    const query = this.b.ref<HTMLTextAreaElement>(queryRef);
    query.addEventListener("input", () => {
      dispatch({ type: "QUERY_CHANGED", query: query.value });
    });
    query.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key !== "Enter" || e.shiftKey) return;
      e.preventDefault();
      const text = query.value.trim();
      if (text === "") return;
      dispatch({ type: "ACTION", action: { type: "query", text } });
    });

    // The popup hands the question over to this box: it cannot take focus
    // itself without dropping the selection, so the pane takes it here, once
    // the pane is actually on screen.
    this.unsubscribe = ctx.bus.subscribe((event) => {
      if (event.type === "learning:focus-query") query.focus();
    });

    this.b.bindVisible(emptyRef, (s) => s.selection === null && !s.overlapping);
    this.b.bindVisible(
      markListRef,
      (s) => s.selection === null && !s.overlapping && s.marks.length > 0,
    );
    this.b.bindList(markListRef, "li", (s) =>
      s.marks.map((mark) =>
        showKeyed(mark.thread, MarkItem, { text: mark.text }, {}, () =>
          dispatch({ type: "MARK_CLICKED", thread: mark.thread }),
        ),
      ),
    );
    this.b.bindVisible(warnRef, (s) => s.overlapping);
    this.b.bindVisible(bodyRef, (s) => s.selection !== null && !s.overlapping);
    this.b.bindText(quoteRef, (s) => s.selection ?? "");
    this.b.bindValue(queryRef, (s) => s.query);
  }

  sync(state: State): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.unsubscribe();
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

import { type Citation, parse, resolve } from "../citation.ts";
import {
  type GraphChange,
  type GraphEdge,
  type GraphNode,
  isNodeId,
  KnowledgeGraph,
  type NodeId,
} from "../graph.ts";
import { changesIn, readTools, writeTools } from "../graph-tools.ts";
import type {
  Chip,
  Citations,
  Msg as GraphMsg,
  Sidebar,
  Viewport,
} from "../graph-view.ts";
import { IDENTITY_VIEWPORT, panZoom } from "../graph-view.ts";
import { interactionAt } from "../interactions.ts";
import { layout, type Position } from "../layout.ts";
import {
  clearSnapshot,
  type InteractionAddress,
  interactionAddresses,
  loadSnapshot,
  saveSnapshot,
  toSnapshot,
} from "../persistence.ts";
import { GRAPH_UPDATE_SYSTEM, graphUpdatePrompt } from "../prompt.ts";
import {
  type SampleId,
  selectedSample,
  selectSample,
} from "../samples/index.ts";
import { type Anchor, overlaps, type ThreadId } from "../selection.ts";
import { type Message, type MessageIdx, runThread, Thread } from "../thread.ts";
import { ThreadTree } from "../threads.ts";
import { PostRenderEventBus } from "../vamp.ts";
import {
  type AppEvent,
  AppView,
  type GraphUpdate,
  type Msg,
  type State,
  type UpdatePaneState,
  type Updates,
} from "../view.ts";

/** The editable fields of a node or edge: the id addresses it, so it is not
 * part of what the sidebar edits. */
function draftOf(node: GraphNode): Omit<GraphNode, "id">;
function draftOf(edge: GraphEdge): Omit<GraphEdge, "id">;
function draftOf<T extends { id: string }>(item: T): Omit<T, "id"> {
  const { id: _id, ...rest } = item;
  return rest;
}

/** What an update thread did, read off its own transcript: a call that never
 * finished parsing or came back an error changed nothing, so it reports
 * nothing. */
function changesOf(
  messages: ReadonlyArray<Message>,
): ReadonlyArray<GraphChange> {
  return messages.flatMap((m) =>
    m.type === "tool_use" && m.call.input && m.call.result?.status === "ok"
      ? [...changesIn(m.call.result.text)]
      : [],
  );
}

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the task transcript, with learning threads hanging off the
 * passages the user picks out of it. */
export function mount(container: HTMLElement): void {
  // One socket for the whole app: every Thread adds its own
  // listener and drops frames whose requestId it does not own, so streams
  // interleave over the single connection.
  const socket = connect();
  const opened =
    socket.readyState === WebSocket.OPEN
      ? Promise.resolve()
      : new Promise<void>((resolve) => {
          socket.addEventListener("open", () => {
            resolve();
          });
        });
  const sample = selectedSample();
  const snapshot = loadSnapshot(sample?.id);
  // Scoped to the user, not to a thread: it outlives every thread in the tree
  // and is discarded only by a page load.
  const graph = snapshot
    ? KnowledgeGraph.from(snapshot.graph)
    : new KnowledgeGraph();
  const onChange = () => {
    refresh();
    view.sync(state);
    save();
  };
  const tree = snapshot
    ? ThreadTree.restore(
        socket,
        snapshot.threads,
        snapshot.root,
        snapshot.nextThreadId,
        onChange,
        (s) =>
          new Thread(socket, {
            system: s.system,
            seed: s.seed,
            initialTurns: [...s.log],
            // Not persisted: a thread's tools are a fact about what kind of
            // thread it is, and the root has none.
            tools: s.origin ? readTools(graph) : undefined,
          }),
      )
    : new ThreadTree(
        socket,
        new Thread(socket, { initialTurns: sample?.turns }),
        onChange,
      );
  // The thread on the left. Moved only by the arrows.
  let focus = tree.root;
  // The live selection, and where on screen it ended. It carries the thread it
  // is over, so it is one variable whether the user dragged in the left pane or
  // in the reflect thread; which pane shows it is derived in refresh().
  let anchor: Anchor | null = null;
  let anchorAt: { x: number; y: number } | null = null;
  let sidebar: Sidebar = { type: "closed" };
  // Pan and zoom live beside the sidebar rather than in the view: the view
  // holds no state of its own, and a rebuild of the graph must not recentre it.
  let viewport: Viewport = IDENTITY_VIEWPORT;
  // Graph updates run one at a time: two in flight would each be handed the
  // pre-update graph and mint rival nodes for the same concept. Appending to
  // this chain is the whole serialization.
  let updates: Promise<void> = Promise.resolve();
  // What each interaction's update is doing, keyed by its address. Derived from
  // the update thread's own tool calls, so it cannot disagree with what the
  // model actually did.
  const address = (thread: ThreadId, index: MessageIdx) => `${thread}:${index}`;
  // Only finished updates are persisted: one that was still running when the
  // page went away comes back missing, which is what re-enqueues it.
  const graphUpdates = new Map<string, GraphUpdate>(
    (snapshot?.updates ?? []).map((u) => [
      address(u.thread, u.index),
      { type: "done", changes: u.changes, messages: u.messages },
    ]),
  );

  function save(): void {
    saveSnapshot(
      toSnapshot({
        sample: sample?.id,
        tree,
        graph,
        updates: [...graphUpdates].flatMap(([key, update]) => {
          if (update.type !== "done") return [];
          const [thread, index] = key.split(":");
          return [
            {
              thread: thread as ThreadId,
              index: Number(index) as MessageIdx,
              changes: update.changes,
              messages: update.messages,
            },
          ];
        }),
        build: state.build,
      }),
    );
  }
  function updatesFor(thread: ThreadId): Updates {
    const out = new Map<number, GraphUpdate>();
    for (const [key, update] of graphUpdates) {
      const [id, index] = key.split(":");
      if (id === thread) out.set(Number(index), update);
    }
    return out;
  }
  // The layout is a few hundred iterations, and refresh() runs on every
  // keystroke, so it is recomputed only when the shape of the graph changes.
  let placement = new Map<NodeId, Position>();
  let placedFor = "";
  // The shape a layout is currently being computed for, if any.
  let placing: string | null = null;
  // Purely presentational, and per thread: which messages the user has
  // expanded past the collapsed height.
  const expanded = new Map<ThreadId, Set<number>>();
  // The address of the graph update whose transcript the right pane is
  // reviewing, and the expansion state of its messages.
  let updateFocus: string | null = null;
  const updateExpanded = new Map<string, Set<number>>();
  function updateExpandedFor(key: string): Set<number> {
    let set = updateExpanded.get(key);
    if (!set) {
      set = new Set();
      updateExpanded.set(key, set);
    }
    return set;
  }
  function expandedFor(id: ThreadId): Set<number> {
    let set = expanded.get(id);
    if (!set) {
      set = new Set();
      expanded.set(id, set);
    }
    return set;
  }

  const state: State = {
    sample: sample?.id ?? "",
    messages: [],
    inFlight: false,
    draft: "",
    split: false,
    depth: 0,
    canDescend: false,
    thread: focus,
    marks: [],
    activeMark: null,
    anchor: null,
    popup: null,
    tab: "threads",
    graph: {
      status: "ready",
      nodes: [],
      edges: [],
      viewport,
      sidebar,
      citations: { description: [], notes: [] },
    },
    build: snapshot?.build ?? { type: "idle" },
    query: "",
    expanded: new Set(),
    updates: new Map(),
    child: null,
    updatePane: null,
  };

  /** Re-projects the tree onto the view's state. Everything but the fields the
   * user is editing is derived, so this runs after every dispatch. */
  /** The graph projected onto view state: positions from `layout`, and the
   * sidebar the user is editing. */
  function refreshGraph(): void {
    const nodes = graph.nodes;
    const edges = graph.edges;
    const shape = [
      ...nodes.map((n) => n.id),
      ...edges.map((e) => `${e.id}:${e.from}->${e.to}`),
    ].join(",");
    if (shape !== placedFor && shape !== placing) {
      placing = shape;
      // Deferred so the browser paints the pending state before the
      // simulation blocks the main thread. If the graph has moved on by the
      // time this lands, the next refresh schedules another run.
      setTimeout(() => {
        placement = layout(graph);
        placedFor = shape;
        placing = null;
        sync();
      }, 0);
    }
    const pending = shape !== placedFor;
    const at = (id: NodeId): Position =>
      placement.get(id) ?? { x: 0.5, y: 0.5 };
    state.graph = {
      status: pending ? "pending" : "ready",
      nodes: pending ? [] : nodes.map((n) => ({ ...n, pos: at(n.id) })),
      edges: pending
        ? []
        : edges.map((e) => ({ ...e, from_: at(e.from), to_: at(e.to) })),
      viewport,
      sidebar,
      citations: citationsOf(),
    };
  }

  /** The citations in the *saved* prose of whatever the sidebar has open. Read
   * off the graph rather than the draft: a half-typed address is not a
   * citation, and one that does not resolve against the tree is not either. */
  function citationsOf(): Citations {
    const chips = (text: string): Chip[] =>
      parse(text).flatMap((span) => {
        if (span.type !== "citation") return [];
        const quote = resolve(tree, span.citation);
        return quote === undefined ? [] : [{ citation: span.citation, quote }];
      });
    switch (sidebar.type) {
      case "closed":
        return { description: [], notes: [] };
      case "edge": {
        const edge = graph.edge(sidebar.id);
        return { description: chips(edge?.description ?? ""), notes: [] };
      }
      case "node": {
        const node = graph.node(sidebar.id);
        return {
          description: chips(node?.description ?? ""),
          notes: chips(node?.notes ?? ""),
        };
      }
    }
  }

  function refresh(): void {
    refreshGraph();
    const node = tree.get(focus);
    state.thread = focus;
    state.depth = state.split ? tree.path(focus).length : 0;
    state.canDescend = node.activeChild !== null;
    state.messages = node.thread.messages;
    state.inFlight = node.thread.inFlight;
    state.draft = node.draft;
    state.marks = tree.marks(focus);
    state.expanded = expandedFor(focus);
    state.updates = updatesFor(focus);
    state.updatePane = updatePane();
    state.activeMark = node.activeChild;
    state.anchor = anchor?.thread === focus ? anchor : null;
    state.popup = popupAt();
    const activeChild = node.activeChild;
    if (!activeChild) {
      state.child = null;
      return;
    }
    const child = tree.get(activeChild);
    state.child = {
      thread: activeChild,
      messages: child.thread.messages,
      inFlight: child.thread.inFlight,
      draft: child.draft,
      expanded: expandedFor(activeChild),
      updates: updatesFor(activeChild),
      marks: tree.marks(activeChild),
      anchor: anchor?.thread === activeChild ? anchor : null,
    };
  }

  /** Where the floating actions go, or null for no popup. They stand in for the
   * reflect pane wherever it is not on screen: at layer 0, and beside a
   * selection made in the reflect thread itself, which has no pane of its own.
   * A passage that already owns a thread offers nothing. */
  function popupAt(): { x: number; y: number } | null {
    if (!anchor || !anchorAt) return null;
    if (overlaps(tree.marks(anchor.thread), anchor)) return null;
    if (anchor.thread === focus) return state.split ? null : anchorAt;
    return anchor.thread === tree.get(focus).activeChild ? anchorAt : null;
  }

  /** The update transcript on the right, live while its thread is still
   * running: it is read straight off the same record the chips come from. */
  function updatePane(): UpdatePaneState | null {
    if (updateFocus === null) return null;
    const update = graphUpdates.get(updateFocus);
    if (!update) return null;
    return {
      messages: update.messages,
      running: update.type === "running",
      expanded: updateExpandedFor(updateFocus),
    };
  }

  function sync(): void {
    refresh();
    view.sync(state);
    save();
  }

  /** One detached thread per user interaction, writing straight into the graph
   * through its tools. Queued against every other update rather than run
   * concurrently, and never awaited by the user: the learning thread answers
   * them regardless, and a failure here is invisible outside the console. */
  function queueGraphUpdate(
    thread: ThreadId,
    index: MessageIdx,
  ): Promise<string | null> {
    const interaction = interactionAt(tree, thread, index);
    const key = address(thread, index);
    graphUpdates.set(key, { type: "running", messages: [] });
    // The update thread's transcript, as of its last change: the chips are read
    // off the calls it actually made, not off a side channel, and the same
    // transcript is what the review pane shows.
    let transcript: ReadonlyArray<Message> = [];
    const done = updates
      .then(async () => {
        // Read inside the queued step, so this update sees the previous one's
        // writes rather than the graph as it stood when it was enqueued.
        const result = await runThread(socket, {
          system: GRAPH_UPDATE_SYSTEM,
          prompt: graphUpdatePrompt(interaction, graph.render()),
          tools: writeTools(graph),
          yieldSchema: "void",
          onChange: (messages) => {
            transcript = messages;
            graphUpdates.set(key, { type: "running", messages });
            sync();
          },
        });
        if (result.status === "error") {
          console.error(result.error);
          return String(result.error);
        }
        return null;
      })
      .catch((e: unknown) => {
        console.error(e);
        return String(e);
      })
      .then((error) => {
        graphUpdates.set(key, {
          type: "done",
          changes: changesOf(transcript),
          messages: transcript,
        });
        sync();
        return error;
      });
    updates = done.then(() => undefined);
    return done;
  }

  /** The sample's own turns: a loaded transcript is a session that happened
   * before this page existed, so no live update ever ran over it. Every turn
   * after these came from an interaction that updated the graph itself, so
   * enumerating once at mount is what keeps the build from double-counting. */
  const sampleTurnCount = (sample?.turns ?? []).filter(
    (t) => t.role === "user",
  ).length;
  const sampleInteractions: MessageIdx[] = tree
    .get(tree.root)
    .thread.messages.flatMap((m, i) =>
      m.role === "user" && m.type === "text" ? [i as MessageIdx] : [],
    )
    .slice(0, sampleTurnCount);

  function advanceBuild(key: string, error: string | null): void {
    const build = state.build;
    if (build.type !== "running") return;
    state.build = {
      type: "running",
      done: build.done + 1,
      total: build.total,
      failures:
        error === null
          ? build.failures
          : [...build.failures, { address: key, error }],
    };
  }

  function finishBuild(): void {
    const build = state.build;
    if (build.type !== "running") return;
    state.build = { type: "done", failures: build.failures };
  }

  /** Walks the loaded sample's turns through the same queue the live updates
   * use, so an interaction mid-build interleaves rather than races. */
  function runBuild(): void {
    if (state.build.type !== "idle") return;
    const total = sampleInteractions.length;
    if (total === 0) return;
    state.build = { type: "running", done: 0, total, failures: [] };
    void drain(
      sampleInteractions.map((index) => ({ thread: tree.root, index })),
    );
  }

  /** Pushes a backlog of interactions through the update queue, one at a time,
   * advancing the build indicator for the ones the build owns. */
  async function drain(
    addresses: ReadonlyArray<InteractionAddress>,
  ): Promise<void> {
    // A backlog is drained straight out of mount, before the socket has
    // finished connecting; every other send is behind a user action.
    await opened;
    const owned = new Set(sampleInteractions);
    for (const { thread, index } of addresses) {
      const error = await queueGraphUpdate(thread, index);
      if (thread === tree.root && owned.has(index))
        advanceBuild(address(thread, index), error);
      sync();
    }
    finishBuild();
    sync();
  }
  function send(id: ThreadId): void {
    const node = tree.get(id);
    const text = node.draft.trim();
    if (text === "" || node.thread.inFlight) return;
    node.draft = "";
    // Nothing is streaming while the thread is idle, so the turn lands at the
    // end of `messages` - which is its citable address.
    const index = node.thread.messages.length as MessageIdx;
    node.thread.send(text).then(undefined, (e: unknown) => {
      console.error(e);
    });
    void queueGraphUpdate(id, index);
  }

  /** A citation run forwards: focus the cited thread and put the cited message
   * in front of the user. Focusing a deep thread is just setting each
   * ancestor's `activeChild`, which is the same state a mark click sets, so
   * this introduces no second notion of focus. The scroll cannot happen here -
   * the pane is not showing that thread until after the sync - so it goes out
   * on the post-render bus. */
  function reveal(state: State, citation: Citation): void {
    const path = tree.path(citation.thread);
    path.forEach((id, i) => {
      const next = path[i + 1];
      if (next) tree.get(id).activeChild = next;
    });
    focus = citation.thread;
    state.split = path.length > 1;
    state.tab = "threads";
    anchor = null;
    anchorAt = null;
    state.query = "";
    updateFocus = null;
    bus.emit({ type: "transcript:reveal", index: citation.index });
  }

  /** The graph tab's own reducer. It writes to the graph and to `sidebar`;
   * everything the canvas shows is re-derived in refreshGraph(). */
  function updateGraph(msg: GraphMsg): void {
    switch (msg.type) {
      case "SELECT_NODE": {
        const node = graph.node(msg.id);
        if (!node) break;
        sidebar = {
          type: "node",
          id: node.id,
          draft: draftOf(node),
          error: null,
        };
        break;
      }
      case "SELECT_EDGE": {
        const edge = graph.edge(msg.id);
        if (!edge) break;
        sidebar = {
          type: "edge",
          id: edge.id,
          draft: draftOf(edge),
          error: null,
        };
        break;
      }
      case "CLOSE":
        sidebar = { type: "closed" };
        break;
      case "NODE_FIELD":
        if (sidebar.type === "node") sidebar.draft[msg.field] = msg.value;
        break;
      case "LEVEL_CHANGED":
        if (sidebar.type === "node") sidebar.draft.level = msg.level;
        break;
      case "EDGE_FIELD":
        if (sidebar.type === "edge") sidebar.draft[msg.field] = msg.value;
        break;
      case "SAVE": {
        if (sidebar.type === "closed") break;
        const result =
          sidebar.type === "node"
            ? graph.putNode({ id: sidebar.id, ...sidebar.draft })
            : graph.putEdge({ id: sidebar.id, ...sidebar.draft });
        // A rejected save keeps the draft, so the user's typing survives.
        sidebar.error = result.status === "error" ? result.error : null;
        break;
      }
      case "DELETE": {
        if (sidebar.type === "closed") break;
        if (sidebar.type === "node") graph.deleteNode(sidebar.id);
        else graph.deleteEdge(sidebar.id);
        sidebar = { type: "closed" };
        break;
      }
      case "PAN":
      case "ZOOM":
      case "RESET_VIEW":
        viewport = panZoom(viewport, msg);
        break;
    }
  }

  /** Puts a background update's own transcript on the right. This is review,
   * not descent: nothing hangs off the pane, and closing it hands the right
   * column back to whatever was there. */
  function showUpdate(thread: ThreadId, index: number): void {
    const key = address(thread, index as MessageIdx);
    if (!graphUpdates.has(key)) return;
    updateFocus = key;
    state.split = true;
    anchor = null;
    anchorAt = null;
  }

  function update(state: State, msg: Msg): void {
    const node = tree.get(focus);
    switch (msg.type) {
      case "DRAFT_CHANGED":
        node.draft = msg.draft;
        break;
      case "SAMPLE_CHANGED":
        selectSample(msg.id === "" ? undefined : (msg.id as SampleId));
        break;
      case "RESET":
        clearSnapshot(sample?.id);
        window.location.reload();
        break;
      case "TAB_CHANGED":
        state.tab = msg.tab;
        break;
      case "CHANGE_CLICKED":
        state.tab = "graph";
        updateGraph(
          isNodeId(msg.id)
            ? { type: "SELECT_NODE", id: msg.id }
            : { type: "SELECT_EDGE", id: msg.id },
        );
        break;
      case "GRAPH_MSG":
        if (msg.msg.type === "CITATION_CLICKED")
          reveal(state, msg.msg.citation);
        else updateGraph(msg.msg);
        break;
      case "SUBMIT":
        send(focus);
        break;
      case "BUILD":
        runBuild();
        break;
      case "GO_DEEPER": {
        if (!state.split) {
          state.split = true;
          break;
        }
        const child = node.activeChild;
        if (!child) break;
        focus = child;
        anchor = null;
        anchorAt = null;
        state.query = "";
        updateFocus = null;
        break;
      }
      case "GO_BACK": {
        const parent = node.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        // Climbing out lands on the passage that was descended through, which
        // may be far up a long transcript.
        const active = tree.get(focus).activeChild;
        if (active) bus.emit({ type: "mark:reveal", thread: active });
        anchor = null;
        anchorAt = null;
        state.query = "";
        updateFocus = null;
        break;
      }
      case "TOGGLE_EXPANDED": {
        const set = expandedFor(focus);
        if (!set.delete(msg.index)) set.add(msg.index);
        break;
      }
      case "SELECTION_CHANGED":
        anchor = msg.anchor;
        anchorAt = msg.at;
        // The right column is where this selection's actions go, so whatever
        // was there gives way - but only while the split is showing; at layer 0
        // the popup carries them and the active child must survive, since it is
        // what `→` descends into.
        if (state.split) node.activeChild = null;
        updateFocus = null;
        break;
      case "MARK_CLICKED":
        anchor = null;
        anchorAt = null;
        node.activeChild = msg.thread;
        // Clicking a mark at layer 0 is how the reflect column is opened onto
        // the thread behind it: this thread stays on the left, its thread
        // appears beside it.
        state.split = true;
        bus.emit({ type: "mark:reveal", thread: msg.thread });
        updateFocus = null;
        break;
      case "SHOW_UPDATE":
        showUpdate(focus, msg.index);
        break;
      case "UPDATE_MSG":
        switch (msg.msg.type) {
          case "CLOSE":
            updateFocus = null;
            break;
          case "TOGGLE_EXPANDED": {
            if (updateFocus === null) break;
            const set = updateExpandedFor(updateFocus);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
        }
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const from = anchor;
            if (!from || overlaps(tree.marks(from.thread), from)) break;
            // Opening from the reflect thread hangs the new thread off it, so
            // the left pane moves down to the thread that was selected in.
            if (from.thread !== focus) focus = from.thread;
            state.split = true;
            updateFocus = null;
            const id = tree.open(from, msg.msg.action, {
              tools: readTools(graph),
              graph: graph.render(),
            });
            anchor = null;
            anchorAt = null;
            state.query = "";
            void queueGraphUpdate(id, 0 as MessageIdx);
            tree
              .get(id)
              .thread.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "ASK": {
            // Not an action: it opens the pane on this passage and leaves the
            // ask to the user, so no thread exists yet.
            const from = anchor;
            if (!from || overlaps(tree.marks(from.thread), from)) break;
            focus = from.thread;
            state.split = true;
            updateFocus = null;
            bus.emit({ type: "learning:focus-query" });
            break;
          }
          case "MARK_CLICKED":
            anchor = null;
            anchorAt = null;
            node.activeChild = msg.msg.thread;
            updateFocus = null;
            bus.emit({ type: "mark:reveal", thread: msg.msg.thread });
            break;
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = node.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
          case "TOGGLE_EXPANDED": {
            const set = expandedFor(activeChild);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
          case "CHANGE_CLICKED":
            update(state, msg.msg);
            break;
          case "SHOW_UPDATE":
            showUpdate(activeChild, msg.msg.index);
            break;
          case "SELECTION_CHANGED":
            // No pane clearing: the actions for this one are the popup, and
            // the thread it was made in has to stay on screen under it.
            anchor = msg.msg.anchor;
            anchorAt = msg.msg.at;
            break;
          case "MARK_CLICKED":
            // A mark in the reflect thread names a thread one layer further
            // down, so showing it is a descent.
            anchor = null;
            anchorAt = null;
            focus = activeChild;
